{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/charts",
  "data": [
    {
      "name": "series",
      "type": "readonly SeriesDef[]",
      "description": "Series definitions used to derive tooltip rows and hover dots. Chart supplies this automatically through its tooltip prop; direct composition should pass the same array used by Chart.",
      "default": "[]"
    },
    {
      "name": "render",
      "type": "(xValue: unknown, seriesValues: TooltipSeriesValue[]) => ReactNode",
      "description": "Replaces the default card body. Return null to hide the card while preserving enabled hover indicators and dots.",
      "default": "Default grouped value content"
    },
    {
      "name": "hoverIndicator",
      "type": "boolean",
      "description": "Shows a band highlight for bar series on a band scale, or a vertical crosshair for other series.",
      "default": "true"
    },
    {
      "name": "showHoverDots",
      "type": "boolean",
      "description": "Shows a point marker for each eligible non-bar series at the hovered index.",
      "default": "true"
    },
    {
      "name": "placement",
      "type": "'auto' | 'right' | 'left' | 'top'",
      "description": "Selects one of the shipped placement algorithms. The current implementation positions from the hovered x coordinate and the plot top; whether placement should instead be point-relative on both axes remains unresolved. Custom renderers own their content sizing.",
      "default": "'auto'"
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
